From ae773c3b1134a0df15efc47d482e2a993b3c6211 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:40:34 +0100
Subject: [PATCH] WindowResizeHandler: Make popup corners easier to grab for
 resizing

Each edge of a popup was only hit-tested within its own margin, so a
diagonal resize needed a press in a corner of a few pixels. Like window
decorations, a press on an edge near a corner now resizes both ways.

BUG: 527999
---
 src/plasmaquick/windowresizehandler.cpp | 20 ++++++++++++++++++++
 1 file changed, 20 insertions(+)

diff --git a/src/plasmaquick/windowresizehandler.cpp b/src/plasmaquick/windowresizehandler.cpp
index 620337614..628a5fa16 100644
--- a/src/plasmaquick/windowresizehandler.cpp
+++ b/src/plasmaquick/windowresizehandler.cpp
@@ -7,6 +7,8 @@
 #include "windowresizehandler.h"

 #include <QEvent>
+#include <QFontMetrics>
+#include <QGuiApplication>
 #include <QMouseEvent>
 #include <QWindow>

@@ -143,6 +145,24 @@ Qt::Edges WindowResizeHandlerPrivate::hitTest(const QPointF &pos)
     bool right = hitTestRight(pos);
     bool top = hitTestTop(pos);
     bool bottom = hitTestBottom(pos);
+
+    const QRect geometry = window->geometry();
+    const int corner = 2 * QFontMetrics(QGuiApplication::font()).boundingRect(QLatin1Char('M')).height();
+    if (top || bottom) {
+        if (pos.x() < geometry.x() + margins.left() + corner) {
+            left = true;
+        } else if (pos.x() >= geometry.x() + geometry.width() - margins.right() - corner) {
+            right = true;
+        }
+    }
+    if (left || right) {
+        if (pos.y() < geometry.y() + margins.top() + corner) {
+            top = true;
+        } else if (pos.y() >= geometry.y() + geometry.height() - margins.bottom() - corner) {
+            bottom = true;
+        }
+    }
+
     Qt::Edges edges;
     if (left) {
         edges.setFlag(Qt::LeftEdge);
